message.content:
{
  "globalIssues": [
    "일부 카드 효과와 이벤트 보상 간의 수치적 정합성 검토 필요",
    "카드 획득 조건 및 비용 설계에서 '정답'이 고정되는 경향이 있어 선택의 전략적 다양성 보완 필요"
  ],
  "cards": [
    {
      "key": "shiro_analysis",
      "verdict": "revise",
      "reasons": "evolution의 goal(6000)이 현재 맵의 일반적인 수치 체계에서 어느 정도 수준인지 명확하지 않음. 또한 grade 1임에도 효과 수치(8%)가 다른 grade 2 카드들과 비교했을 때 낮게 설정됨.",
      "suggestedChange": "evolution goal을 맵의 난이도에 맞춰 재조정하거나, grade 1에 걸맞은 기초 수치로 조정 필요."
    },
    {
      "key": "saber_guard",
      "verdict": "accept",
      "reasons": "방어 키워드에 충실한 기초 능력치 제공.",
      "suggestedChange": null
    },
    {
      "key": "saber_opening",
      "verdict": "revise",
      "reasons": "grade 2임에도 불구하고 evolution이 kind 3(상위 단계)으로 바로 점프하며, goal이 60으로 매우 낮게 설정되어 있어 밸런스 붕괴 위험이 있음.",
      "suggestedChange": "evolution goal을 상향 조정하거나, evolution 단계를 단계적으로 설계할 것."
    },
    {
      "key": "rin_disarm",
      "verdict": "accept",
      "reasons": "관통 및 치명타 확률이라는 고유 속성을 잘 반영함.",
      "suggestedChange": null
    },
    {
      "key": "archer_pragmatism",
      "verdict": "accept",
      "reasons": "보스전 특화 수치를 명확히 구분함.",
      "suggestedChange": null
    },
    {
      "key": "assassin_spacing",
      "verdict": "revise",
      "reasons": "치명타 피해 25%는 grade 2 치고 매우 높음. 또한 evolution goal(60)이 saber_opening과 동일하여 수치적 일관성 부족.",
      "suggestedChange": "치명타 피해 수치를 하향 조정하거나, evolution goal을 차별화할 것."
    },
    {
      "key": "sakura_meal",
      "verdict": "accept",
      "reasons": "회복과 최대 체력 증가를 통해 생존력을 높이는 의도가 명확함.",
      "suggestedChange": null
    },
    {
      "key": "caster_channel",
      "verdict": "accept",
      "reasons": "흡수와 최대 체력 감소라는 리스크-리턴 구조가 원작의 마력 운용과 잘 부합함.",
      "suggestedChange": null
    }
  ],
  "nextDraftGuidance": [
    "카드들의 evolution goal 수치를 맵 전체의 레벨링 구조에 맞춰 통일성 있게 재설정할 것.",
    "특정 카드가 압도적으로 유리한 선택지가 되지 않도록, 골드/물약/밀집도 등의 변수를 더 정교하게 배분할 것."
  ],
  "events": [
    {
      "key": "school_circle",
      "verdict": "revise",
      "reasons": "세 번째 선택지(술식 기록을 넘기고...)가 카드 획득도 없고 골드도 없으며 물약만 1개 주는 것으로, 다른 두 선택지에 비해 보상이 지나치게 빈약하여 플레이어의 선택 동기가 약함.",
      "suggestedChange": "세 번째 선택지에 소량의 골드나 밀집도 감소 등의 추가 보상을 부여하여 전략적 가치를 높일 것."
    },
    {
      "key": "school_circle_trace",
      "verdict": "accept",
      "reasons": "각 선택지의 리스크(자금 소모, 체력 감소)와 리턴(카드 획득, 자금 확보)이 명확하게 구분됨.",
      "suggestedChange": null
    },
    {
      "key": "saber_practice",
      "verdict": "accept",
      "reasons": "수련의 성격에 맞는 세 가지 선택지가 잘 구성됨.",
      "suggestedChange": null
    },
    {
      "key": "temple_gate",
      "verdict": "revise",
      "reasons": "두 번째 선택지(세이버와 공격할 틈을 만든다)가 saber_opening 카드를 주지만 비용이 200으로 높음. 첫 번째 선택지(관찰)와 비교했을 때 관찰 선택지의 밀집도 증가 페널티가 적절한지 검토 필요.",
      "suggestedChange": "관찰 선택지의 밀집도 증가 수치를 높이거나, 세이버 선택지의 비용을 조정하여 밸런스를 맞출 것."
    }
  ]
}
